using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class CDVerify {
 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Saved B2 required");string r=Path.GetFullPath(Path.Combine(Application.dataPath,"../../..")),h=r+"/SourceAssets/B2_CeilingDensity/",o=r+"/Docs/Review/2026-11-10_B2_CeilingDensity/";var all=s.GetRootGameObjects().Where(g=>g.name.StartsWith("B2_")).SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;var paths=all.Select(PathOf).ToHashSet();var old=JArray.Parse(File.ReadAllText(h+"before.json"));var renderers=all.Where(t=>t.gameObject.activeInHierarchy).Select(t=>t.GetComponent<MeshRenderer>()).Where(m=>m&&m.enabled).ToArray();var origFloors=JArray.Parse(File.ReadAllText(h+"floors.json"));var floorGeometry=new List<object>();foreach(var q in origFloors){string name=(string)q["name"];var t=all.Single(t=>t.name==name);var original=old.Single(v=>(string)v["name"]==name);var source=AssetDatabase.LoadAllAssetsAtPath((string)original["mesh"]).OfType<Mesh>().First();var copy=t.GetComponent<MeshFilter>().sharedMesh;floorGeometry.Add(new{name,verticesUnchanged=source.vertices.SequenceEqual(copy.vertices),trianglesUnchanged=source.triangles.SequenceEqual(copy.triangles),colliderPreserved=t.GetComponent<MeshCollider>()&&t.GetComponent<MeshCollider>().sharedMesh==source});}
 var models=new List<object>();foreach(string path in Directory.GetFiles("Assets/Afrer_Seconds/05.Model/Environment/B2","CD_*.fbx")){var mesh=AssetDatabase.LoadAllAssetsAtPath(path).OfType<Mesh>().First();var vs=mesh.vertices;var tri=mesh.triangles;int degenerate=0;for(int i=0;i<tri.Length;i+=3)if(Vector3.Cross(vs[tri[i+1]]-vs[tri[i]],vs[tri[i+2]]-vs[tri[i]]).sqrMagnitude<1e-16f)degenerate++;models.Add(new{path,vertices=vs.Length,triangles=tri.Length/3,degenerate});}
 var missingMeshes=renderers.Where(m=>!m.GetComponent<MeshFilter>()||!m.GetComponent<MeshFilter>().sharedMesh).Select(m=>m.name).ToArray();var missingMats=renderers.Where(m=>m.sharedMaterials.Any(a=>!a)).Select(m=>m.name).ToArray();var guidance=all.Single(t=>t.name=="B2_DestinationGuidance");var lcd=renderers.SelectMany(m=>m.sharedMaterials).Where(m=>m&&m.name.StartsWith("BR_Display_0")&&(m.name.EndsWith("01")||m.name.EndsWith("02"))).Distinct().Select(m=>new{m.name,emission=m.IsKeywordEnabled("_EMISSION"),map=AssetDatabase.GetAssetPath(m.GetTexture("_EmissionMap"))}).ToArray();var result=new{saved=!s.isDirty,originalTransforms=old.Count,missingOriginal=old.Where(v=>!paths.Contains((string)v["path"])).Select(v=>(string)v["path"]).ToArray(),missingMeshes,missingMats,floors=floorGeometry,newModels=models,activeGuidance=guidance.gameObject.activeInHierarchy,lcd,lights=all.Select(t=>t.GetComponent<Light>()).Count(l=>l&&l.gameObject.activeInHierarchy&&l.enabled),consoles=all.Count(t=>t.name.Contains("_MachineryConsole_Visual")&&t.gameObject.activeInHierarchy)};File.WriteAllText(o+"final_state.json",JsonConvert.SerializeObject(result,Formatting.Indented));return result;}
}
